function v3_actuator_export(r,s,folder)
t=r.delta_actual.Time(:);idx=unique([1:20:numel(t),numel(t)]);t=t(idx);d=interp1(r.delta_actual.Time,squeeze(r.delta_actual.Data),t,'previous','extrap');rate=interp1(r.delta_dot.Time,squeeze(r.delta_dot.Data),t,'previous','extrap');dc=interp1(r.delta_cmd.Time,squeeze(r.delta_cmd.Data),t,'previous','extrap');cmd=interp1(r.commands.Time,squeeze(r.commands.Data),t,'previous','extrap');ta=interp1(r.tau_actual.Time,squeeze(r.tau_actual.Data),t,'previous','extrap');nu=zeros(numel(t),4);nc=nu;tc=zeros(numel(t),3);H=tc;
if s.cmg,nu=interp1(r.nu_actual.Time,squeeze(r.nu_actual.Data),t,'previous','extrap');nc=cmd(:,4:7);tc=interp1(r.cmg_torque.Time,squeeze(r.cmg_torque.Data),t,'previous','extrap');H=interp1(r.cmg_H.Time,squeeze(r.cmg_H.Data),t,'previous','extrap');end
gamma=nan(numel(t),4);geometry=zeros(numel(t),10);if s.cmg,p=vehicle_params;state=interp1(r.states.Time,squeeze(r.states.Data),t,'previous','extrap');gamma=state(:,7:10);for j=1:numel(t),g=gamma(j,:);A=p.cmg.h0*(-p.s0.*sin(g)+p.gxs0.*cos(g));L=max(-p.cmg.gdot_max,nu(j,:)-p.cmg.gddot_max*.2);U=min(p.cmg.gdot_max,nu(j,:)+p.cmg.gddot_max*.2);C=-A;positive=sum(max(C,0).*U+min(C,0).*L,2);negative=-sum(max(C,0).*L+min(C,0).*U,2);static=sum(abs(A),2)*p.cmg.gdot_max;geometry(j,:)=[min(svd(A)),positive',negative',static'];end;end
names={'time_s','elevator_actual_rad','aileron_actual_rad','rudder_actual_rad','elevator_rate_radps','aileron_rate_radps','rudder_rate_radps','elevator_command_rad','aileron_command_rad','rudder_command_rad','nu1_actual_radps','nu2_actual_radps','nu3_actual_radps','nu4_actual_radps','nu1_command_radps','nu2_command_radps','nu3_command_radps','nu4_command_radps','aero_request_x_Nm','aero_request_y_Nm','aero_request_z_Nm','aero_actual_x_Nm','aero_actual_y_Nm','aero_actual_z_Nm','cmg_actual_x_Nm','cmg_actual_y_Nm','cmg_actual_z_Nm','Hx_Nms','Hy_Nms','Hz_Nms'};names=[names,{'gamma1_actual_rad','gamma2_actual_rad','gamma3_actual_rad','gamma4_actual_rad','sigma_min','next_x_positive_support_Nm','next_y_positive_support_Nm','next_z_positive_support_Nm','next_x_negative_support_Nm','next_y_negative_support_Nm','next_z_negative_support_Nm','static_x_projection_Nm','static_y_projection_Nm','static_z_projection_Nm'}];writetable(array2table([t,d,rate,dc,nu,nc,cmd(:,1:3),ta,tc,H,gamma,geometry],'VariableNames',names),fullfile(folder,'actuator_timeseries_20ms.csv'));
file=fullfile(folder,'pid_diagnostics.mat');if isfile(file),d=load(file);fields={'tau_ref','tau_a_request','tau_cmg_request','tau_total_request','residual','nu_base','nu','delta_star','delta_lower','delta_upper','H','unload_a','unload_c'};M=d.times(:);names={'time_s'};for j=1:numel(fields),key=fields{j};value=cell2mat(cellfun(@(z)z.(key)(:)',d.history,'UniformOutput',false)');M=[M value];for k=1:size(value,2),names{end+1}=sprintf('%s_%d',key,k);end;end;eta=cellfun(@(z)z.eta,d.history)';M=[M eta];names{end+1}='unload_scale';T=array2table(M,'VariableNames',names);T.pause_reason=string(cellfun(@(z)z.reason,d.history,'UniformOutput',false)');T.unload_enabled=repmat(s.pid.unload,height(T),1);writetable(T,fullfile(folder,'pid_allocation_timeseries.csv'));end
end
